#requires -version 5.1
$ErrorActionPreference='Stop'
$projectRoot=Split-Path $PSScriptRoot -Parent
Set-Location -LiteralPath $projectRoot
Import-Module (Join-Path $projectRoot 'app\CleanData\MemoryClear.Disk.psm1') -Force
$results=New-Object 'System.Collections.Generic.List[object]'
function Assert {param([bool]$Condition,[string]$Message='Assertion failed');if(-not$Condition){throw $Message}}
function Check {param([string]$Name,[scriptblock]$Test);try{&$Test;$results.Add([pscustomobject]@{Name=$Name;Passed=$true;Error=''})}catch{$results.Add([pscustomobject]@{Name=$Name;Passed=$false;Error=$_.Exception.Message})}}
$root=Join-Path $projectRoot ('artifacts\disk-fixture-'+[guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $root|Out-Null
[IO.File]::WriteAllText((Join-Path $root '.memoryclear-fixture'),'Readonly app-data catalog fixture')
$context=[pscustomobject]@{Local=(Join-Path $root 'Local');Roaming=(Join-Path $root 'Roaming')}
$catalogRoots=@(Get-MCDiskAppRoots $context)
foreach($entry in $catalogRoots){New-Item -ItemType Directory -Path $entry.Root -Force|Out-Null}
$chrome=$catalogRoots[0].Root;$edge=$catalogRoots[1].Root;$code=$catalogRoots[2].Root
function FixtureFile {param([string]$Path);New-Item -ItemType Directory -Path (Split-Path $Path -Parent) -Force|Out-Null;[IO.File]::WriteAllText($Path,'Test-owned data must remain unchanged')}
$files=@((Join-Path $chrome 'Default\Cache\Cache_Data\data_0'),(Join-Path $chrome 'Default\Network\Cookies'),(Join-Path $edge 'Profile 2\GPUCache\data_1'),(Join-Path $code 'CachedData\version\code.bin'),(Join-Path $code 'User\workspaceStorage\cache\state.vscdb'),(Join-Path $code 'Backups\work.txt'))
foreach($file in $files){FixtureFile $file}
$before=@($files|ForEach-Object{(Get-FileHash -LiteralPath $_).Hash})
$inventory=[pscustomobject]@{Apps=@();Complete=$true}
$dependencies=[pscustomobject]@{Entries=@();CapturedUtc=[DateTime]::UtcNow;Complete=$true}
Check 'Catalog readonly/provenance and three scoped roots' {$p=Get-MCDiskAppCatalog;Assert ($p.profiles.Count-eq3-and-not$p.executionEnabled-and$p.governs-eq'product_runtime');foreach($entry in $catalogRoots){Assert ([MemoryClear.Storage.FileInventory]::Within($entry.Root,$root));Assert ($entry.Profile.sources.Count-gt0)}}
Check 'Recognizes cache under exact browser profile and VS Code root' {foreach($file in @($files[0],$files[2],$files[3])){$r=Resolve-MCDiskAppData $file $context;Assert ($r.DataClass-eq'CacheCandidate'-and-not$r.DeletionAllowed) $file}}
Check 'Browser sensitive and offline branches stay protected' {foreach($branch in @('Network\Cookies','Bookmarks','Login Data','History','Sessions\session_1','Service Worker\CacheStorage\offline.db','IndexedDB\state.db','Local Storage\data.db')){$r=Resolve-MCDiskAppData (Join-Path $chrome ('Default\'+$branch)) $context;Assert ($r.DataClass-eq'ProtectedUserData'-and-not$r.DeletionAllowed) $branch}}
Check 'VS Code settings history workspace state and unsaved backups stay protected' {foreach($branch in @('User\settings.json','User\History\file.txt','User\workspaceStorage\Cache\state.db','Backups\unsaved.txt')){$r=Resolve-MCDiskAppData (Join-Path $code $branch) $context;Assert ($r.DataClass-eq'ProtectedUserData') $branch}}
Check 'Unknown/custom layouts and cache-like sibling paths never become cache' {foreach($branch in @('CustomProfile\Cache\data','Profile 0\Cache\data','Default\Cache-old\data','Default\Downloads\Cache\data','Default\Cache')){$r=Resolve-MCDiskAppData (Join-Path $chrome $branch) $context;Assert ($r.DataClass-eq'UnknownAppData') $branch};Assert ($null-eq(Resolve-MCDiskAppData ($code+'-other\Cache\data') $context))}
$data=Resolve-MCDiskAppData $files[0] $context
Check 'Missing complete inventory only labels residual candidate, never verified uninstall' {$r=Resolve-MCDiskAppLifecycle $data $inventory $dependencies;Assert ($r.State-eq'ResidualCandidateUnverified'-and-not$r.DeletionAllowed-and$r.Risk-eq'Blocked')}
Check 'Name plus publisher metadata protects installed product; display name alone does not prove ownership' {$i=[pscustomobject]@{Complete=$true;Apps=@([pscustomobject]@{Name='Google Chrome';Publisher='Google LLC';Location='C:\Fixture\Chrome';Source='Fixture'})};$r=Resolve-MCDiskAppLifecycle $data $i $dependencies;Assert ($r.State-eq'InstalledCatalogProtected');$i.Apps[0].Publisher='Unknown';$r=Resolve-MCDiskAppLifecycle $data $i $dependencies;Assert ($r.State-eq'ResidualCandidateUnverified'-and-not$r.DeletionAllowed)}
Check 'Incomplete or stale dependencies cannot be called an unreferenced residual' {foreach($mode in @('stale','future','incomplete','null')){$d=[pscustomobject]@{Entries=@();Complete=($mode-ne'incomplete');CapturedUtc=[DateTime]::UtcNow};if($mode-eq'stale'){$d.CapturedUtc=[DateTime]::UtcNow.AddHours(-1)};if($mode-eq'future'){$d.CapturedUtc=[DateTime]::UtcNow.AddHours(1)};if($mode-eq'null'){$d=$null};$r=Resolve-MCDiskAppLifecycle $data $inventory $d;Assert ($r.State-eq'UnknownLifecycleProtected') $mode}}
Check 'Possible process/service/task references protect catalog data even at portable executable paths' {foreach($kind in @('Process','Service','Task')){$d=[pscustomobject]@{Entries=@([pscustomobject]@{Kind=$kind;Name='Fixture';Executable='C:\Fixture\Portable\chrome.exe'});CapturedUtc=[DateTime]::UtcNow;Complete=$true};$r=Resolve-MCDiskAppLifecycle $data $inventory $d;Assert ($r.State-eq'PossibleReferenceProtected'-and-not$r.DeletionAllowed)}}
Check 'Native marked catalog scan returns class and identity with no delete authority' {$script:scan=Get-MCDiskScan -AppData -FixtureRoots @($root);Assert ($scan.Rows.Count-eq6-and$scan.Status-eq'CompletedReadonly'-and$scan.AppRootObservations.Count-eq3) ($scan|ConvertTo-Json -Depth 3 -Compress);Assert (@($scan.Rows|Where-Object{$_.DataEvidence.DataClass-eq'CacheCandidate'}).Count-eq3);Assert (@($scan.Rows|Where-Object{$_.DeletionEnabled-or$_.Risk-ne'Blocked'}).Count-eq0)}
Check 'Analysis attaches lifecycle to catalog data without losing classification' {$r=Get-MCDiskOwnerAnalysis $scan -FixtureInventory $inventory -FixtureDependencies $dependencies;Assert ($r.Rows.Count-eq6-and$r.Rows[0].OwnerEvidence.State-eq'ResidualCandidateUnverified'-and-not$r.Rows[0].DeletionEnabled-and$r.Rows[0].DataEvidence.ProfileId)}
Check 'Native directory observation distinguishes empty, absent and nonempty without deleting' {$empty=Join-Path $root 'Empty';New-Item -ItemType Directory -Path $empty|Out-Null;$p=[MemoryClear.Storage.FileInventory]::ProbeDirectory($empty);Assert ($p.State-eq'EmptyAtObservation'-and$p.Identity-and$p.AncestorIdentity);Assert (([MemoryClear.Storage.FileInventory]::ProbeDirectory((Join-Path $root 'Absent'))).State-eq'Absent');Assert (([MemoryClear.Storage.FileInventory]::ProbeDirectory($chrome)).State-eq'Present');Assert (Test-Path -LiteralPath $empty)}
Check 'Junction catalog root is unavailable and outside data never scanned' {$r=Join-Path $projectRoot ('artifacts\disk-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path (Join-Path $r 'Roaming') -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $r '.memoryclear-fixture'),'Junction fixture');New-Item -ItemType Junction -Path (Join-Path $r 'Roaming\Code') -Target $code|Out-Null;$x=Get-MCDiskScan -AppData -FixtureRoots @($r);Assert ($x.Status-eq'Partial'-and$x.Rows.Count-eq0-and$x.AppRootObservations[2].Probe.State-eq'Unavailable')}
Check 'Absent default app roots are normal absence, not a false failed scan' {$r=Join-Path $projectRoot ('artifacts\disk-fixture-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $r|Out-Null;[IO.File]::WriteAllText((Join-Path $r '.memoryclear-fixture'),'Absent profile fixture');$x=Get-MCDiskScan -AppData -FixtureRoots @($r);Assert ($x.Status-eq'NoEligibleRoots'-and$x.Rows.Count-eq0-and@($x.AppRootObservations|Where-Object{$_.Probe.State-ne'Absent'}).Count-eq0)}
Check 'Scope combination rejected and pre-cancelled scan visits no files' {$failed=$false;try{Get-MCDiskScan -AppData -IncludeLargeFiles -FixtureRoots @($root)|Out-Null}catch{$failed=$true};Assert $failed;$cts=New-Object Threading.CancellationTokenSource;try{$cts.Cancel();$r=Get-MCDiskScan -AppData -FixtureRoots @($root) -CancellationToken $cts.Token;Assert ($r.Status-eq'Cancelled'-and$r.Rows.Count-eq0)}finally{$cts.Dispose()}}
Check 'All fixture data hashes and paths unchanged after scan/analysis' {$after=@($files|ForEach-Object{(Get-FileHash -LiteralPath $_).Hash});Assert (($before-join',')-eq($after-join','))}
$report=[pscustomobject]@{Timestamp=[DateTime]::UtcNow.ToString('o');Runtime=$PSVersionTable.PSVersion.ToString();Passed=@($results|Where-Object{$_.Passed}).Count;Failed=@($results|Where-Object{-not$_.Passed}).Count;Results=$results.ToArray();Scope='Native marked fixtures; synthetic install/dependency evidence; readonly app catalog';RealUserCleanupExecuted=$false;Unverified=@('Version-specific vendor cache semantics and custom profiles','Historical uninstall positive proofs','Live provider coverage and Windows10/11 VM matrix')}
$report|ConvertTo-Json -Depth 6|Set-Content (Join-Path $projectRoot 'docs\verification\disk-app-profile-tests.json') -Encoding UTF8
$results|Format-Table -AutoSize|Out-String|Write-Output
if($report.Failed){exit 1}
